}

/* Input Group Styling */
.input-group-append .btn {
  border-radius: 0 8px 8px 0;
}

/* Responsive Design */
@media (max-width: 768px) {
  .banking-form-widget {
    padding: 15px;
  }
  .step-tracker {
    flex-wrap: wrap;
    gap: 10px;
  }
  .step-item {
    flex-basis: calc(50% - 5px);
    margin-bottom: 15px;
  }
  .step-item:not(:last-child)::after {
    display: none;
  }
  .form-content {
    padding: 20px;
  }
  .signature-row {
    flex-direction: column;
  }
}

/* Animation for step transitions */
.step-content {
  animation: fadeInUp var(--transition-time) ease-in-out;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Progress indicator */
.progress-container {
  margin: 20px 0;
}

.progress {
