sp_widget.script:
(function($sp) {

    data.message = '';
    data.url = '';	
    data.sys_id = '';

	var glideRecordEntity = new GlideRecordSecure("x_vuram_financia_0_fcc_kyc_entity_details");
	var table = 'x_vuram_financia_0_fcc_kyc_entity_details';

    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
	if (input && input.action === "upload") {
    try {

      if (glideRecordEntity.get(input.recordSysId)) {
        var gsaa= new GlideSysAttachment();
        var attachmentSysId = gsaa.writeBase64(
          glideRecordEntity,
          input.fileName,   // filename
          input.fileType,   // MIME type
          input.fileContent // Base64 string
        );

        // map to specific field if provided
        if (input.fieldName) {
          glideRecordEntity.setValue(input.fieldName, attachmentSysId);
          glideRecordEntity.update();
        }

        data.success = true;
        data.attachmentSysId = attachmentSysId;
      } else {
        data.success = false;
        data.error = "Record not found: " + input.recordSysId;
      }
    } catch (e) {
      data.success = false;
      data.error = e.message;
    }
  }

    var userEmail = gs.getUser().getEmail();

    // Create record (NO status update here)
    if (input && input.action === 'createRecord') {
        glideRecordEntity.addQuery('email_id', userEmail);
        glideRecordEntity.query();

        if (glideRecordEntity.next()) {
            // just return sys_id
            data.sys_id = glideRecordEntity.sys_id.toString();
        }
    }

    // Get QR record
    if (input && input.action === 'getRecord') {
        if (glideRecordEntity.get(input.sys_id)) {
            data.url = glideRecordEntity.getValue('video_kyc_link');
        }
    }

    // Update status when proceeding
    if (input && input.action === 'markStarted') {
        if (glideRecordEntity.get(input.sys_id)) {
            glideRecordEntity.video_kyc_status = "started";
            glideRecordEntity.update();
            data.message = 'Record updated as started';
        }
    }




    var user = gs.getUser();

    if (input && input.action === 'upload_financial') {
        try {
            if (glideRecordEntity.get(input.recordSysId)) {
                var gsa = new GlideSysAttachment();

                // Save attachment into sys_attachment table
                var newId = gsa.writeBase64(
                    glideRecordEntity, // target record
                    "FINANCIAL_STATEMENT_" + input.fileName, // file name
                    input.fileType, // mime type
                    input.fileContent // base64 string
                );

                // (Optional) update reference field if your table has one
                if (glideRecordEntity.isValidField("upload_audited_financial_statement")) {
                    glideRecordEntity.upload_audited_financial_statement = newId;
                    glideRecordEntity.update();
                }

                data.success = true;
                data.attachmentSysId = newId;
            } else {
                data.success = false;
                data.error = "Entity record not found for sys_id: " + input.recordSysId;
            }
        } catch (e) {
            data.success = false;
            data.error = e.message;
        }
        return; // stop here so it won’t run submit logic
    }
    if (input && input.action == 'submit') {


        var x = 0;
        var record = JSON.parse(input.record);
        arr_vy = [].concat(record.nonIndividuals, record.individuals, record.controllers, record.authorizedSigners);
        var glideRecordOwnership = new GlideRecordSecure('x_vuram_financia_0_fcc_kyc_ownerships');
        glideRecordOwnership.addQuery('fcc_kyc_case.entity.email_id', userEmail);
        glideRecordOwnership.orderByDesc('number');
        glideRecordOwnership.setLimit(9);
        glideRecordOwnership.query();
        while (glideRecordOwnership.next()) {

            if (glideRecordOwnership.type != 'entity') {
                glideRecordOwnership.first_name = arr_vy[x].first_name;
                glideRecordOwnership.middle_name = arr_vy[x].middle_name;
                glideRecordOwnership.last_name = arr_vy[x].last_name;
                glideRecordOwnership.address_line = arr_vy[x].address_line;
                glideRecordOwnership.postal_code = arr_vy[x].postal_code;
                glideRecordOwnership.city = arr_vy[x].city;
                glideRecordOwnership.dob = arr_vy[x].dob;
                glideRecordOwnership.country_of_residence = arr_vy[x].country_of_residence;
                glideRecordOwnership.country_of_nationality = arr_vy[x].country_of_nationality;
            } else {
                glideRecordOwnership.full_legal_name = arr_vy[x].full_legal_name.toString();
                glideRecordOwnership.address_line = arr_vy[x].address_line.toString();
                glideRecordOwnership.postal_code = arr_vy[x].postal_code.toString();
                glideRecordOwnership.city = arr_vy[x].city.toString();
                glideRecordOwnership.country_of_incorporation = arr_vy[x].country_of_incorporation.toString();
            }
            x++;
            if (glideRecordOwnership.update()) { 
            } else
                gs.addErrorMessage("Not updated" + glideRecordOwnership.number);


        }


        enq = "email_id=" + userEmail;
        glideRecordEntity.addQuery('email_id', userEmail);
        glideRecordEntity.query();

        if (glideRecordEntity.next()) {
					  glideRecordEntity.listing_details = record.listingProof;
            glideRecordEntity.legal_name = record.legalName;
            glideRecordEntity.doing_business_as_name = record.doingBusinessAsName;
            glideRecordEntity.sic = record.sic;
					  glideRecordEntity.same_as_legal_address=record.sameAsLegal;
            glideRecordEntity.sic_description = record.sicDescription;
            glideRecordEntity.customer_type = record.customerType;
            glideRecordEntity.product_services = record.productServices;
            glideRecordEntity.registration_number = record.registrationNumber;
            glideRecordEntity.customer_sub_type = record.customerSubType;
            glideRecordEntity.country_of_domicile = record.domicileCountry;
            glideRecordEntity.describe_legal_entity_type_free_text = record.legalEntityDescription;
            glideRecordEntity.is_the_customer_traded_on_an_exchange = record.isTradedOnExchange;
            glideRecordEntity.if_listed_which_country_it_is_listed = record.listedCountriesSelected.toString();
            glideRecordEntity.primary_country_of_assets = record.primaryAssetsCountry;
            glideRecordEntity.legal_street_address = record.legalStreetAddress;
            glideRecordEntity.legal_postal_code = record.legalPostalCode;
            glideRecordEntity.legal_city = record.legalCity;
            glideRecordEntity.legal_country = record.legalCountry;
            glideRecordEntity.physical_street_address = record.physicalStreet;
            glideRecordEntity.physical_postal_code = record.physicalPostalCode;
            glideRecordEntity.physical_city = record.physicalCity;
            glideRecordEntity.physical_country = record.physicalCountry;
            glideRecordEntity.local_currency = record.currencyType;
            glideRecordEntity.total_assets.setDisplayValue(record.currencyType + ";" + record.totalAssets);
            glideRecordEntity.amount_in_usd.setDisplayValue("USD;" + record.amountInUSD);
            glideRecordEntity.describe_the_source_of_annual_revenue = record.annualRevenueSource;
            glideRecordEntity.cheque_withdrawal = record.chequeWithdrawal
            glideRecordEntity.atm_withdrawal = record.atmWithdrawal;
            glideRecordEntity.ach_withdrawal = record.achWithdrawal;
            glideRecordEntity.cash_withdrawal = record.cashWithdrawal;
            glideRecordEntity.ach_deposit = record.achDeposit;
            glideRecordEntity.cheque_deposit = record.chequeDeposit;
            glideRecordEntity.cash_deposit = record.cashDeposit;
            glideRecordEntity.as_of_date = record.asOfDate;
            glideRecordEntity.amount_in_local_currency.setDisplayValue(record.currencyType + ";" + record.amountInLocal);
            glideRecordEntity.annual_revenue.setDisplayValue("USD;" + record.annualRevenue);
            glideRecordEntity.estimated_annual_transaction_volume = record.transactionVolume;
            glideRecordEntity.describe_the_customer_significant_suppliers_free_text = record.significantSuppliers;
            glideRecordEntity.countries_of_the_customer_s_significant_suppliers = record.listedCountriesSelectedd.toString();
            glideRecordEntity.nature_of_business = record.natureOfBusiness;
            glideRecordEntity.is_there_significant_private_ownership = record.privateOwnership;


            if (glideRecordEntity.update()) {
                data.status_of_submit = true;
                data.individual_sys_id = glideRecordEntity.sys_id;
                var glideRecordCase = new GlideRecordSecure("x_vuram_financia_0_fcc_kyc_cases");
                glideRecordCase.addQuery('entity', glideRecordEntity.sys_id);
                glideRecordCase.query();

                if (glideRecordCase.next()) {
                    glideRecordCase.state = 150;
                    glideRecordCase.assigned_to = '';
                    if (glideRecordCase.update()) {
                        data.case_updated = true;
                        data.case_sys_id = glideRecordCase.sys_id;
                    } else {
                        data.case_updated = false;
                    }
                }

            } else {
                data.status_of_submit = false;
            }
            gs.info('Updated record with sys_id: ' + glideRecordEntity.sys_id);
        } else {
            gs.info("No Entity Found");
        }


    gs.info("==== OWNERSHIP SUBMIT TRIGGERED ====");

    // --------------------------
    // Parse double-encoded record
    // --------------------------
    var rec = {};
    try {
        rec = JSON.parse(input.record);
        gs.info("Parsed Record Object: " + JSON.stringify(rec));
    } catch (e) {
        gs.error("FAILED TO PARSE input.record: " + e);
        return;
    }

    // Helper: Insert ownership entry
    function insertOwnership(type, obj) {

        gs.info("Creating " + type + " record with data: " + JSON.stringify(obj));

        var glideRecordEntity = new GlideRecordSecure("x_vuram_financia_0_fcc_kyc_ownerships");

			gs.info("Glide to ownership table completed");
       glideRecordEntity.initialize();

			gs.info("Table initialized");

        glideRecordEntity.type = type;

        // Your table fields:
        glideRecordEntity.first_name = obj.first_name || "";
        glideRecordEntity.last_name = obj.last_name || "";
        glideRecordEntity.address_line = obj.address_line || "";
        glideRecordEntity.postal_code = obj.postal_code || "";
        glideRecordEntity.city = obj.city || "";
        glideRecordEntity.dob = obj.dob || "";
        glideRecordEntity.country_of_residence = obj.country_of_residence || "";
        glideRecordEntity.country_of_nationality = obj.country_of_nationality || "";

        var sys_id = glideRecordEntity.insert();
        gs.info("Inserted ownership record sys_id = " + sys_id);
    }

    // --------------------------
    // INDIVIDUALS
    // --------------------------
    gs.info("Individuals received: " + JSON.stringify(rec.individuals));

    if (rec.individuals && rec.individuals.length > 0) {
        rec.individuals.forEach(function(ind, idx) {
            gs.info("Processing Individual #" + idx);
            insertOwnership("individual", ind);
        });
    } else {
        gs.info("No Individuals found.");
    }

    // --------------------------
    // NON-INDIVIDUALS (ENTITY)
    // --------------------------
    gs.info("Non-Individuals received: " + JSON.stringify(rec.nonIndividuals));

    if (rec.nonIndividuals && rec.nonIndividuals.length > 0) {
        rec.nonIndividuals.forEach(function(entity, idx) {
            gs.info("Processing Non-Individual Entity #" + idx);
            insertOwnership("entity", entity);
        });
    } else {
        gs.info("No Non-Individuals found.");
    }

    // --------------------------
    // CONTROLLERS
    // --------------------------
    gs.info("Controllers received: " + JSON.stringify(rec.controllers));

    if (rec.controllers && rec.controllers.length > 0) {
        rec.controllers.forEach(function(ctrl, idx) {
            gs.info("Processing Controller #" + idx);
            insertOwnership("controller", ctrl);
        });
    } else {
        gs.info("No Controllers found.");
    }

    // --------------------------
    // AUTHORIZED SIGNERS
    // --------------------------
    gs.info("Authorized Signers received: " + JSON.stringify(rec.authorizedSigners));

    if (rec.authorizedSigners && rec.authorizedSigners.length > 0) {
        rec.authorizedSigners.forEach(function(sign, idx) {
            gs.info("Processing Authorized Signer #" + idx);
            insertOwnership("authorized_signers", sign);
        });
    } else {
        gs.info("No Authorized Signers found.");
    }

    gs.info("==== OWNERSHIP INSERT COMPLETED ====");



    }

    var sysIds = [];

    glideRecordEntity.addQuery('email_id', userEmail);
    glideRecordEntity.query();

    if (glideRecordEntity.next()) {

        data.sys_id = glideRecordEntity.sys_id.toString();
        data.legal_name = glideRecordEntity.getValue('legal_name');
        data.doing_business_as_name = glideRecordEntity.doing_business_as_name.toString();
        //data.doing_business_as_name = glideRecordEntity.legal_name.toString();
			  data.same_as_legal_address=glideRecordEntity.same_as_legal_address;
        data.sic = glideRecordEntity.sic.toString();
        data.customer_type = glideRecordEntity.customer_type.toString();
        data.product_services = glideRecordEntity.product_services.toString();
        data.registration_number = glideRecordEntity.registration_number.toString();
        data.country_of_domicile = glideRecordEntity.country_of_domicile.toString();
        data.customer_sub_type = glideRecordEntity.customer_sub_type.toString();
        data.sic_description = glideRecordEntity.sic_description.toString();
        data.describe_legal_entity_type_free_text = glideRecordEntity.describe_legal_entity_type_free_text.toString();
        data.is_the_customer_traded_on_an_exchange = glideRecordEntity.is_the_customer_traded_on_an_exchange;
        data.if_listed_which_country_it_is_listed = glideRecordEntity.if_listed_which_country_it_is_listed;
        data.primary_country_of_assets = glideRecordEntity.primary_country_of_assets.toString();
        data.legal_street_address = glideRecordEntity.legal_street_address.toString();
        data.legal_postal_code = glideRecordEntity.legal_postal_code.toString();
        data.legal_city = glideRecordEntity.legal_city.toString();
        data.legal_country = glideRecordEntity.legal_country.toString();
        data.physical_street_address = glideRecordEntity.physical_street_address.toString();
        data.physical_postal_code = glideRecordEntity.physical_postal_code.toString();
        data.physical_city = glideRecordEntity.physical_city.toString();
        data.physical_country = glideRecordEntity.physical_country.toString();
        data.total_assets = glideRecordEntity.total_assets.getValue();
        data.amount_in_usd = glideRecordEntity.amount_in_usd.getValue();
        data.describe_the_source_of_annual_revenue = glideRecordEntity.describe_the_source_of_annual_revenue.toString();
        data.local_currency = glideRecordEntity.local_currency.getValue();
        data.cheque_withdrawal = glideRecordEntity.cheque_withdrawal.getValue();
        data.atm_withdrawal = glideRecordEntity.atm_withdrawal.getDisplayValue();
        data.ach_withdrawal = glideRecordEntity.ach_withdrawal.getDisplayValue();
        data.cash_deposit = glideRecordEntity.cash_deposit.getValue();
        data.cash_withdrawal = glideRecordEntity.cash_withdrawal.getDisplayValue();
        data.ach_deposit = glideRecordEntity.ach_deposit.getDisplayValue();
        data.cheque_deposit = glideRecordEntity.cheque_deposit.getDisplayValue();
        data.as_of_date = glideRecordEntity.as_of_date.toString();
        data.amount_in_local_currency = glideRecordEntity.amount_in_local_currency.getValue();
        data.annual_revenue = glideRecordEntity.annual_revenue.getValue();
        data.estimated_annual_transaction_volume = glideRecordEntity.estimated_annual_transaction_volume.getDisplayValue();
        data.describe_the_customer_significant_suppliers_free_text = glideRecordEntity.describe_the_customer_significant_suppliers_free_text.toString();
        data.countries_of_the_customer_s_significant_suppliers = glideRecordEntity.countries_of_the_customer_s_significant_suppliers.toString();
        data.nature_of_business = glideRecordEntity.nature_of_business.toString();
        data.is_there_significant_private_ownership = glideRecordEntity.is_there_significant_private_ownership;

        if (!gs.nil(glideRecordEntity.controllers)) {
            sysIds = sysIds.concat(glideRecordEntity.controllers.split(','));
        }
        if (!gs.nil(glideRecordEntity.individual_10_ownership)) {
            sysIds = sysIds.concat(glideRecordEntity.individual_10_ownership.split(','));
        }
        if (!gs.nil(glideRecordEntity.non_individual_10_ownership)) {
            sysIds = sysIds.concat(glideRecordEntity.non_individual_10_ownership.split(','));
        }
        if (!gs.nil(glideRecordEntity.authorised_signers)) {
            sysIds = sysIds.concat(glideRecordEntity.authorised_signers.split(','));
        }


    }

    // Remove blanks & duplicates
    sysIds = sysIds.filter(function(id) {
        return id && id.trim();
    });

    data.individuals = [];
