                country_of_nationality: glideRecordCaseOwnership.country_of_nationality.toString()

            });
        } else if (glideRecordCaseOwnership.type == 'authorized_signers') {
            data.authorizedSigners.push({
                first_name: glideRecordCaseOwnership.first_name.toString(),
                middle_name: glideRecordCaseOwnership.middle_name.toString(),
                last_name: glideRecordCaseOwnership.last_name.toString(),
                address_line: glideRecordCaseOwnership.address_line.toString(),
